const encoder=new TextEncoder(),decoder=new TextDecoder();
const to64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.slice(i,i+8192));return btoa(s)};
const from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
export async function deriveKey(passphrase,salt){if(passphrase.length<12)throw Error('Use a passphrase of at least 12 characters.');const material=await crypto.subtle.importKey('raw',encoder.encode(passphrase),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
export async function createVault(passphrase){const salt=crypto.getRandomValues(new Uint8Array(16)),key=await deriveKey(passphrase,salt);return {key,salt}}
export async function encryptState(state,vault){const iv=crypto.getRandomValues(new Uint8Array(12)),bytes=await crypto.subtle.encrypt({name:'AES-GCM',iv},vault.key,encoder.encode(JSON.stringify(state)));return {version:1,encrypted:true,algorithm:'AES-GCM-256/PBKDF2-SHA256',iterations:310000,salt:to64(vault.salt),iv:to64(iv),ciphertext:to64(new Uint8Array(bytes))}}
export async function decryptState(envelope,passphrase){if(envelope.version!==1||envelope.algorithm!=='AES-GCM-256/PBKDF2-SHA256'||envelope.iterations!==310000)throw Error('Unsupported encrypted backup.');const salt=from64(envelope.salt),iv=from64(envelope.iv);if(salt.length!==16||iv.length!==12||envelope.ciphertext.length>100000000)throw Error('Invalid encrypted backup.');const key=await deriveKey(passphrase,salt);try{const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,from64(envelope.ciphertext));return {state:JSON.parse(decoder.decode(bytes)),vault:{key,salt}}}catch{throw Error('The passphrase is incorrect or this backup is damaged.')}}
